public static String applyRelativePath(String path, String relativePath) {
    // Example 1: Remove leading and trailing slashes from the input paths.
    path = path.trim().replaceAll("^/+", "");
    relativePath = relativePath.trim().replaceAll("^/+", "");

    // Example 2: Check if the relative path is an absolute path.
    if (relativePath.startsWith("//")) {
        // If the relative path is an absolute path, return it as is.
        return relativePath;
    }

    // Example 3: Split the input paths into their component parts.
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Example 4: Iterate over the relative path parts and update the path.
    for (int i = 0; i < relativePathParts.length; i++) {
        String part = relativePathParts[i];
        if (part.equals("..")) {
            // If the relative path part is "..", remove the last part from the path.
            if (pathParts.length > 0) {
                pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
            }
        } else if (!part.isEmpty()) {
            // If the relative path part is not "..", add it to the path.
            pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
            pathParts[pathParts.length - 1] = part;
        }
    }

    // Example 5: Join the updated path parts back into a single string.
    return String.join("/", pathParts);
}

