/**
 * Loads thread snapshots in a given time range from a file.
 *
 * @param file The file to load thread snapshots from.
 * @param timeRanges The time ranges to load snapshots for.
 * @return A list of thread snapshots loaded from the file.
 * @throws IOException If an I/O error occurs.
 */
public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    try (BinaryReader reader = new BinaryReader(file)) {
        while (true) {
            long threadId = reader.readLong();
            long startTime = reader.readLong();
            long endTime = reader.readLong();
            long sampleCount = reader.readLong();
            long cpuTime = reader.readLong();
            long semanticsEndTime = reader.readLong();
            long semanticsElapsedTime = reader.readLong();
            String threadName = reader.readString();
            String threadState = reader.readString();
            boolean isDaemon = reader.readBoolean();
            boolean isIdle = reader.readBoolean();
            boolean isRunnable = reader.readBoolean();
            boolean isSuspended = reader.readBoolean();
            boolean isTerminated = reader.readBoolean();
            boolean isTimedWaiting = reader.readBoolean();
            boolean isWaiting = reader.readBoolean();

            ThreadSnapshot snapshot = new ThreadSnapshot(threadId, startTime, endTime, sampleCount, cpuTime, semanticsEndTime, semanticsElapsedTime, threadName, threadState, isDaemon, isIdle, isRunnable, isSuspended, isTerminated, isTimedWaiting, isWaiting);
            if (timeRanges.stream().anyMatch(r -> r.getStartTime() <= startTime && r.getEndTime() >= endTime)) {
                snapshots.add(snapshot);
            }
        }
    }

    return snapshots;
}
